//! `strip_ext` — Strip a TS extension from a `src/`-relative path so it reads as an import specifier (`shared/ui/data/Card.tsx` → `shared/ui/data/Card`).

/// Strip a TS extension from a `src/`-relative path so it reads as an import specifier
/// (`shared/ui/data/Card.tsx` → `shared/ui/data/Card`).
pub(crate) fn strip_ext(path: &str) -> String {
    for ext in [".tsx", ".ts"] {
        if let Some(base) = path.strip_suffix(ext) {
            return base.to_string();
        }
    }
    path.to_string()
}
